<script>
(function () {
  'use strict';

  /* ============ 配置 ============ */
  var STORAGE_KEY = 'fumanlou.bookings.v1';
  var MAX_GUESTS = 20;
  var MAX_NOTE = 120;

  /* ============ 元素引用 ============ */
  var form        = document.getElementById('booking-form');
  var nameInput   = document.getElementById('guest-name');
  var phoneInput  = document.getElementById('guest-phone');
  var dateInput   = document.getElementById('guest-date');
  var timeInput   = document.getElementById('guest-time');
  var guestsInput = document.getElementById('guest-count');
  var noteInput   = document.getElementById('guest-note');
  var noteCount   = document.getElementById('note-count');
  var formStatus  = document.getElementById('form-status');
  var summary     = document.getElementById('booking-summary');
  var summaryId   = document.getElementById('summary-id');
  var summaryBody = document.getElementById('summary-body');
  var bookingsList  = document.getElementById('bookings-list');
  var bookingsEmpty = document.getElementById('bookings-empty');
  var bookingsCount = document.getElementById('bookings-count');
  var resetBtn    = document.getElementById('reset-btn');

  var inputs = [nameInput, phoneInput, dateInput, timeInput, guestsInput, noteInput];

  /* ============ 日期工具 ============ */
  function pad(n) { return n < 10 ? '0' + n : String(n); }

  function todayString() {
    var d = new Date();
    return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
  }

  function setDateMin() {
    dateInput.min = todayString();
  }

  function formatDate(value) {
    var parts = String(value).split('-');
    if (parts.length !== 3) { return String(value); }
    var d = new Date(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]));
    var week = ['周日', '周一', '周二', '周三', '周四', '周五', '周六'][d.getDay()];
    return parts[0] + ' 年 ' + Number(parts[1]) + ' 月 ' + Number(parts[2]) + ' 日（' + week + '）';
  }

  /* ============ 错误提示 ============ */
  function setFieldError(input, message) {
    var box = document.getElementById(input.id + '-error');
    var field = input.closest('.field');
    if (message) {
      input.setAttribute('aria-invalid', 'true');
      if (field) { field.classList.add('is-invalid'); }
      if (box) { box.textContent = message; }
    } else {
      input.removeAttribute('aria-invalid');
      if (field) { field.classList.remove('is-invalid'); }
      if (box) { box.textContent = ''; }
    }
  }

  function clearAllErrors() {
    inputs.forEach(function (input) { setFieldError(input, ''); });
  }

  /* ============ 字段校验 ============ */
  function validateField(input) {
    var value = input.value.trim();
    var message = '';

    switch (input.id) {
      case 'guest-name':
        if (!value) {
          message = '请填写您的姓名。';
        } else if (value.length > 20) {
          message = '姓名请控制在 20 个字以内。';
        }
        break;

      case 'guest-phone':
        if (!value) {
          message = '请填写手机号。';
        } else if (!/^1[3-9]\d{9}$/.test(value)) {
          message = '请输入 11 位有效手机号，例如 13812345678。';
        }
        break;

      case 'guest-date':
        if (!value) {
          message = '请选择用餐日期。';
        } else if (value < todayString()) {
          message = '用餐日期不能早于今天。';
        }
        break;

      case 'guest-time':
        if (!value) {
          message = '请选择用餐时间。';
        }
        break;

      case 'guest-count':
        if (!value) {
          message = '请填写用餐人数。';
        } else if (!/^\d+$/.test(value) || Number(value) < 1 || Number(value) > MAX_GUESTS) {
          message = '用餐人数需为 1–' + MAX_GUESTS + ' 之间的整数，更多人数请致电 010-8888 6666。';
        }
        break;

      case 'guest-note':
        if (value.length > MAX_NOTE) {
          message = '备注请控制在 ' + MAX_NOTE + ' 个字以内。';
        }
        break;
    }

    setFieldError(input, message);
    return message === '';
  }

  /* ============ 本地存储 ============ */
  function loadBookings() {
    try {
      var raw = window.localStorage.getItem(STORAGE_KEY);
      if (!raw) { return []; }
      var data = JSON.parse(raw);
      return Array.isArray(data) ? data : [];
    } catch (err) {
      return [];
    }
  }

  function saveBookings(list) {
    try {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(list));
      return true;
    } catch (err) {
      return false;
    }
  }

  /* ============ 渲染：订台摘要 ============ */
  function showSummary(record) {
    summaryBody.innerHTML = '';

    var rows = [
      ['姓名', record.name],
      ['手机号', record.phone],
      ['用餐日期', formatDate(record.date)],
      ['用餐时间', record.time],
      ['用餐人数', record.guests + ' 位'],
      ['备注', record.note || '无']
    ];

    rows.forEach(function (row) {
      var dt = document.createElement('dt');
      dt.textContent = row[0];
      var dd = document.createElement('dd');
      dd.textContent = row[1];
      summaryBody.appendChild(dt);
      summaryBody.appendChild(dd);
    });

    summaryId.textContent = '订台编号：' + record.id;
    summary.hidden = false;
    summary.focus();
  }

  /* ============ 渲染：已保存订台 ============ */
  function renderBookings() {
    var list = loadBookings();
    bookingsList.innerHTML = '';

    if (!list.length) {
      bookingsEmpty.hidden = false;
      bookingsCount.textContent = '暂无订台记录';
      return;
    }

    bookingsEmpty.hidden = true;
    bookingsCount.textContent = '共 ' + list.length + ' 条订台记录';

    list.forEach(function (record) {
      var li = document.createElement('li');
      li.className = 'booking-item';

      var head = document.createElement('div');
      head.className = 'booking-head';

      var title = document.createElement('h3');
      title.textContent = formatDate(record.date) + ' ' + record.time;

      var tag = document.createElement('span');
      tag.className = 'booking-tag';
      tag.textContent = record.guests + ' 位';

      head.appendChild(title);
      head.appendChild(tag);

      var meta = document.createElement('p');
      meta.className = 'booking-meta';
      meta.textContent = record.name + ' · ' + record.phone + ' · 编号 ' + record.id;

      li.appendChild(head);
      li.appendChild(meta);

      if (record.note) {
        var note = document.createElement('p');
        note.className = 'booking-note';
        note.textContent = '备注：' + record.note;
        li.appendChild(note);
      }

      var del = document.createElement('button');
      del.type = 'button';
      del.className = 'btn btn-danger btn-small';
      del.textContent = '删除此订台';
      del.setAttribute('aria-label',
        '删除 ' + formatDate(record.date) + ' ' + record.time + ' 的订台记录');
      del.addEventListener('click', function () {
        if (!window.confirm('确定删除这条订台记录吗？删除后无法恢复。')) { return; }
        var rest = loadBookings().filter(function (item) {
          return item.id !== record.id;
        });
        saveBookings(rest);
        renderBookings();
        formStatus.classList.remove('is-error');
        formStatus.style.color = 'var(--ok)';
        formStatus.textContent = '已删除该条订台记录。';
      });

      li.appendChild(del);
      bookingsList.appendChild(li);
    });
  }

  /* ============ 备注字数统计 ============ */
  function updateNoteCount() {
    noteCount.textContent = noteInput.value.length + '/' + MAX_NOTE;
  }

  /* ============ 提交 ============ */
  form.addEventListener('submit', function (event) {
    event.preventDefault();

    var firstInvalid = null;
    inputs.forEach(function (input) {
      var ok = validateField(input);
      if (!ok && !firstInvalid) { firstInvalid = input; }
    });

    if (firstInvalid) {
      formStatus.style.color = 'var(--err)';
      formStatus.textContent = '订台信息未填写完整，请检查标红的项目。';
      firstInvalid.focus();
      return;
    }

    var record = {
      id: 'FM-' + Date.now().toString(36).toUpperCase(),
      name: nameInput.value.trim(),
      phone: phoneInput.value.trim(),
      date: dateInput.value,
      time: timeInput.value,
      guests: Number(guestsInput.value),
      note: noteInput.value.trim(),
      createdAt: new Date().toISOString()
    };

    var list = loadBookings();
    list.unshift(record);
    var stored = saveBookings(list);

    if (stored) {
      formStatus.textContent = '';
      formStatus.style.color = 'var(--err)';
    } else {
      formStatus.style.color = 'var(--err)';
      formStatus.textContent = '订台信息已生成，但浏览器本地存储不可用，刷新后可能丢失，请先截图保存。';
    }

    showSummary(record);
    renderBookings();

    form.reset();
    setDateMin();
    updateNoteCount();
    clearAllErrors();
  });

  /* ============ 实时校验与重置 ============ */
  inputs.forEach(function (input) {
    input.addEventListener('blur', function () { validateField(input); });
    input.addEventListener('input', function () {
      if (input.getAttribute('aria-invalid') === 'true') { validateField(input); }
    });
    input.addEventListener('change', function () {
      if (input.getAttribute('aria-invalid') === 'true') { validateField(input); }
    });
  });

  noteInput.addEventListener('input', updateNoteCount);

  resetBtn.addEventListener('click', function () {
    // 让原生 reset 先执行，再清理状态
    window.setTimeout(function () {
      setDateMin();
      updateNoteCount();
      clearAllErrors();
      formStatus.textContent = '';
      formStatus.style.color = 'var(--err)';
      nameInput.focus();
    }, 0);
  });

  /* ============ 初始化 ============ */
  setDateMin();
  updateNoteCount();
  renderBookings();
})();
</script>
</body>
</html>
